class Solution {
    string digits;
    long long memo[20][2][2];
    long long dfs(int pos, int parity, int started, bool tight) {
        if (pos == (int)digits.size()) return started && parity == 0;
        if (!tight && memo[pos][parity][started] != -1)
            return memo[pos][parity][started];
        int limit = tight ? digits[pos] - '0' : 9;
        long long ways = 0;
        for (int d = 0; d <= limit; ++d) {
            int nextStarted = started || d != 0;
            int nextParity = parity ^ (nextStarted && d % 2 == 0);
            ways += dfs(pos + 1, nextParity, nextStarted, tight && d == limit);
        }
        if (!tight) memo[pos][parity][started] = ways;
        return ways;
    }
    long long count(long long x) {
        if (x <= 0) return 0;
        digits = to_string(x);
        memset(memo, -1, sizeof(memo));
        return dfs(0, 0, 0, true);
    }
public:
    long long countEvenlyGoodIntegers(long long l, long long r) {
        return count(r) - count(l - 1);
    }
};
